class LRUCache:
    """
    LRUCache implements a Least Recently Used (LRU) caching mechanism using a
    combination of a hash map for O(1) access and a circular buffer to maintain
    access order for efficient eviction of least recently used items.
    """

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.data = [None] * capacity
        self.index = 0
        self.count = 0

    def get(self, key: int) -> int:
        if key in self.cache:
            return self.cache[key][0]
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache[key][0] = value   # Update the value
        else:
            if self.count < self.capacity:
                self.count += 1
            else:
                # Evict the least recently used item
                to_evict_key = self.data[self.index]
                del self.cache[to_evict_key]
            self.data[self.index] = key
            self.cache[key] = [value, self.index]
            self.index = (self.index + 1) % self.capacity
